    wxGetApp().mainframe->SetTitle(title);
    wxGetApp().mainframe->update_title_colour_after_set_title();
#else
    wxGetApp().mainframe->SetTitle(title + " - OrcaSlicer");
    wxGetApp().mainframe->topbar()->SetTitle(title);
#endif    
}

